	title 'MessageByName'************************************************************************ MessageByName** Copyright 1988,1989* Apple Computer, Inc.* All Rights Reserved.** Original Code by Pete MacDonald* converted to MAX by Steven Glass** This file contains the code to implement the function MessageByName.*** 3/30/89	Mensch* Fixed bug that allowed only 63 byte names instead of 64 byte names.***********************************************************************	include 'all.macros' MACRO&lab moveword &from,&to&lab lda &from sta &to MEND;------------------------------------------;; Equates from procedure MessageData;;------------------------------------------IdNotAvailable	equ $0112	;new error means all Id's used upMessNotFound	equ $0111	;Did not find the requested message.NameTooLong	equ $0113	;Name was longer than 64 chars.MemId	equ $9001	;Mem manager's IDoMessageId	equ 4	;offset in message record to IDIncBusy	equ $e10064	;system utility increment the busy flagBusyStrip	equ $e10180	;" decrement busy, fix stack	DefineStackNumMessages	word	; total number of develper type messagesMessageHandle	long	; general use handle for messagesMaxID	word	; highest ID found during scanPointer	long	; general use pointerNamePtr	long	; pointer to name string (for compare)Direct	wordRTL1	block 3RTL2	block 3RecordPtr	long	; pointer to input recordCreateIt	word	; Create flag.  Used if no msg is found.IDTemp	word	; space supplied by callerCFlag	word	; space supplied by callerlocalbytes	equ Direct-1	;direct -1 = number	of bytes in locals.;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY AddPtr	ENTRY DeLink	ENTRY DerefNGetType	ENTRY DoHoles	ENTRY GetFirst	ENTRY IsitMe	ENTRY Main	ENTRY MakeIt				eject*****************************************************************MessageByName	PROC EXPORT** function MessageByName (CreateFlag : boolean; RecordPtr : LONG ) : LONG** This is the function entry point. It takes 3 inputs.* a word space for the returned ID, a word for the create/found* flag, and a long pointer to the record that contains the name string* that Identifies the the message we want to find/create, as well as* an optional block	of data with which to initialize the message if* it's to be created..*** Inputs:*	space for result	: LONG*	CreateFlag	: WORD*	RecordPtr	: LONG** Outputs:*	CreatedFlag	: WORD*	MessageNumber	: WORD** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	phd	;save direct page under params	tsc	;current stack <Pointer	sec	;ready for subtract	sbc #localbytes	;number of locals	tcs	;new stack <Pointer	tcd	;get the new direct	page-1	stz <NumMessages	;init number of messages counter	stz <MaxId	;init highest Id var.	clc	;init namePtr,	lda <RecordPtr	;so that it points past the	adc #2	;len word in record	sta <NamePtr	lda <RecordPtr+2	adc #0	sta <NamePtr+2	jsl IncBusy	lda [<NamePtr]	;validate length of	string.(source)	and #$00FF	; strip to get the length byte	cmp #65	;is the low byte bigger than 64 ?	blt GoodLen	;taken if not;; was;	bit #$00c0;	beq GoodLen;;?????????????????????????????should we	also check if record len enough for name	lda #NameTooLong	bra SplitGoodLen		; 	jsr Main	;go to workSplit	tax	;pass error to BusyStrip	tsc	;remove locals	clc	adc #LocalBytes	tcs	pld	;and direct page	ldy #6	;num input bytes to	strip for BusyStrip	jml BusyStrip	;This decs busy, fixes stack, sets error	ENDP	title 'MessageByName -- Main'*****************************************************************Main	PROC** Scan all messages	in the developer range (i.e 8000-$ffff)	of message types,* looking for one that contains the same ID string as was requested.* Also noting the number of developer range messages that are used, as well* as the largest used message Id. If no	messages exist at all, then create one* with ID $8000, and set Cflag true indicating that a new message was created* If a message with	the requested Id string is found, then copy the input record* to it, and return	it's Id, set cflag false saying message was not created, but* rather we are returning the ID of an existing message that contains the same* Id String as was requested. If there is no message with the Id String we* are looking for then check NumMessages, and MaxID to see if there are any* holes, if there aren't any holes, (i.e. MaxId - $8000 = NumMessages) and the* last used Id (MaxId = $ffff) then all	Id's are used up, and we return error* # $0112 IdNotAvailable. If MaxId-$8000 > NumMessages, then there is a hole.* At that point the	list is again scanned, until the first hole is found,* and the hole's Id is then the Id used to create the message, and Cflag is* set true indicating a newly created message Id. If there were no holes,* and MaxId < $ffff, then MaxId + 1 is used to create a new	message, and* clag is set true to indicate that we did create a message.*** Inputs:*	all on direct page** Outputs:*	all on direct page** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	jsr GetFirst	;get Pointer to the	first message record	beq NoDevIds	;if 0 then no messagesLoop	jsr DerefNGetType	;deref Handle to Pointer and get type.	tax	;type -> x for later.	bpl AroundAgain	;if < $8000 it's not a developer type	inc <NumMessages	;up count of developer messages found	pushlong <pointer	jsr IsitMe	tay	;is this record the	same type as requ ?	pulllong <pointer	tya	bne NoMatch	;set Z says it was the one I want	stx <IdTemp	;set Id to the one we found,	lda <CreateIt	;pre-check createit	before we call	beq NoMake	;makeit. to insure proper error result.	jsr MakeIt	;re-create message with input recordNoMake	stz <Cflag	;say it's an existing message	rts	;and splitNoMatch	cpx <MaxId	;is Id bigger than biggest found (MaxID)	blt AroundAgain	;taken if current Id < than max ID	stx <MaxId	;current ID is > MaxId so update MaxIDAroundAgain	jsr DeLink	;get and validate forward link	bne Loop	;taken if there is a valid handle	lda <MaxId	;compare to the highest used Id	bpl NoDevIds	;if < $8000 then no	developer Ids exist	and #$7fff	;this works cause we only look at $8000+	inc a	;MaxId + 1 cause we	start at 0 not 1	cmp <NumMessages	;total number of developer messages.	beq NoHoles	;if = then no holes	so check max	jmp DoHoles	;else go find one of the holes.;              rts	!!! EXIT !!!GiveUp	lda #IdNotAvailable	;say all Id's are used up	rtsNoDevIds	MoveWord #$8000,<IdTemp ;set Id to first developer ID	jmp Makeit	;Make 1 with this ID and exit from there;              rts !!!EXIT!!!NoHoles	lda <MaxId	;Get Max Id	inc a	;add one to point at next available	beq GiveUp	;if 0 then none are	left error out.	sta <IdTemp	;maxid+1 = next avaialable ID	jmp Makeit	;use it and make a new message.;              rts !!!EXIT!!!	ENDP	title 'MessageByName -- MakeIt'*****************************************************************MakeIt	PROC** Make a message with the name we were passed, and the Id in IdTemp*** Inputs:*	on direct page** Outputs:*	on direct page** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda <CreateIt	;am I supposed to create a message ?	bne DoMake	;if non 0 then yes,	so continue.	lda #MessNotFound	;Else say the message wasn't found	rts	;and splitDoMake	pha	;handle for message/space for newhandle	pha	clc	;push the len of the record + 6 overhead	lda [<RecordPtr]	;the entire data block i.e. the word len	adc #6	;plus the string, and it's len. + the 6	tax	;bytes of overhead.	lda #0	;synth a high word lda #0 ,rol a. will	rol a	;save one byte versus lda #0, adc #0	pha	;push the hibyte of	the block len.	phx	;and the low byte.	PushWord #MemId	;My ID	PushWord #0	;attributes	pha	;this is the where long. but	pha	;since it's not used. we need't use 0's	_NewHandle	tax	;save error if any	PullLong <MessageHandle ;get the handle	bcc KeepGoing	;if no error keep going.	txa	;recover the error code.	rtsKeepGoing	jsr DerefNGetType	;deref messghandle to Pointer lose type.	lda #6	;set pointer just past the standard	jsr AddPtr	;message overhead of 6 bytes.	lda [<RecordPtr]	;get the record len	tay	;to y for copy	dey	;- 1 cause we copy from len-1 down to 0	sep #$20	LongA OffCopyLp	lda [<RecordPtr],y	;copy the name to handle	sta [<Pointer],y	dey	;next one	bpl CopyLp	rep #$20	LongA On	PushWord #1	;now create a message with the name	PushWord <IdTemp	;we were passed, and the ID we	PushLong <MessageHandle ;found available.	_MessageCenter	pha	;save error result	MoveWord #$ffff,<Cflag ;say we actually	created this recordExit	PushLong <MessageHandle ;dump the handle we created	_DisposeHandle	pla	;recover the error result	rts	;done and split	ENDP	title 'MessageByName -- IsItMe'*****************************************************************IsitMe	PROC** Check to see if the message we got has the same name as was* passed to us by the caller. Z flag is	used to indicate match or not.*** Inputs:*	on direct page** Outputs:*	z-flag** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda #8	;skip the link and Id fields (6)	jsr AddPtr	;and skip word of data len (2)=8 bytes	lda #0000	;set a to zero for when we sep #$20	longa Off	sep #$20	lda [<NamePtr]	;get the name len from input record	cmp [<Pointer]	;(name in message)	bne Exit	;if not same len try next ID	tay	;move len to y for count and indexNameLp	lda [<NamePtr],y	;7 bit compare the name strings.(source)	eor [<Pointer],y	;blend with name in	message	and #$7f	;clear the msb	bne Exit	;if they are same try the next one	dey	;else next char to check	bne NameLp	;don't check the zero'th char.(i.e.Len)Exit	longa on	rep #$20	rts	ENDP	title 'MessageByName -- DoHoles'*****************************************************************DoHoles	PROC** Scan the message list looking for $8000.8001.8002.etc. as	soon* one is not found in the list we know it's a hole, and we use it* to create a message*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	MoveWord #$7fff,<IdTemp ;init counter to look for holesScanLp	jsr GetFirst	;get the handle of the first message.	inc <IdTempLoop	jsr DerefNGetType	;deref Messagehandle to Pointer get type	bpl NextOne	;if taken it's not a developer Id ignore	cmp <IdTemp	;it's a dev Id is it the one we want ?	beq Scanlp	;taken if yes to start over with next IdNextOne	jsr DeLink	;get and validate forward link to next	bne Loop	;taken if there is a valid handle	jmp MakeIt	;if we make it here	Idtemp = Id of hole	ENDP					title 'MessageByName -- Utilities'*********************************************************************** These are various	utility routines.**********************************************************************GetFirst	PROC*********************************************************************** Get handle to the	first message in the list. It happens to be kept* in the memory managers WAP. Leave it in messagehandle**********************************************************************	pha	pha	PushWord #0	;system tool	PushWord #2	;memory managers WAP	_GetWap	;get it	pla	sta <MessageHandle	pla	sta <MessageHandle+2	ora <MessageHandle	;or with low word	rts*********************************************************************** Deref MessageHandle to Pointer. Then return with the message type* In the a-reg.**********************************************************************	entry DerefNGetTypeDerefNGetType		;       	lda [<MessageHandle]	sta <Pointer	;deref/check this message	ldy #2	lda [<MessageHandle],y	sta <Pointer+2	ldy #oMessageID	;offset to message ID	lda [<Pointer],y	;get it	rts*********************************************************************** Add a-reg to Pointer result in Pointer**********************************************************************	entry AddPtrAddPtr		;       	clc	adc <Pointer	sta <Pointer	bcc ExitAddPtr	inc <Pointer+2ExitAddPtr	rts*********************************************************************** Get and validate forward link to next	message. The Z flag	is set or* clear to indicate	whether or not the link is valid or not.**********************************************************************	entry DelinkDelink		;       	lda [<Pointer]	sta <MessageHandle	;get forward link to the	ldy #2	lda [<Pointer],y	sta <MessageHandle+2	ora <MessageHandle	;next one, and validate there is one	rts	ENDP	END